 sec('INITIATIVES','b'),
 fl(['2000 IT Act','2004 NTRO (post-Kargil)','2008 IT Act amended (cyber-terror)','2013 NCSP','2020 National Cyber Security Strategy','2025 DPDP Rules, audit guidelines'],'Evolution',3),
